function MultiStepForm() {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({});

  const goBack = () => {
    // ✅ clear data for current step before going back
    const stepFields = { 2: ['email', 'phone'], 3: ['address', 'city'] };
    const toClear = stepFields[step] || [];
